import java.util.Scanner;

public class Main {
    static final long mod = 1000000007;

    static class Matrix {
        int h, w;
        long[] a;

        Matrix(int n) {
            this.h = n;
            this.w = n;
            this.a = new long[n * n];
        }

        Matrix(int n, int m) {
            this.h = n;
            this.w = m;
            this.a = new long[n * m];
        }

        long get(int r, int c) {
            return a[r * w + c];
        }

        void set(int r, int c, long val) {
            a[r * w + c] = val;
        }

        Matrix add(Matrix m) {
            assert h == m.h && w == m.w;
            Matrix res = new Matrix(h, w);
            for (int i = 0; i < h * w; i++) {
                res.a[i] = (a[i] + m.a[i]) % mod;
            }
            return res;
        }

        Matrix subtract(Matrix m) {
            assert h == m.h && w == m.w;
            Matrix res = new Matrix(h, w);
            for (int i = 0; i < h * w; i++) {
                res.a[i] = (a[i] - m.a[i] + mod) % mod;
            }
            return res;
        }

        Matrix multiply(Matrix m) {
            assert w == m.h;
            Matrix res = new Matrix(h, m.w);
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < m.w; j++) {
                    long sum = 0;
                    for (int k = 0; k < w; k++) {
                        sum += get(i, k) * m.get(k, j);
                    }
                    res.set(i, j, sum % mod);
                }
            }
            return res;
        }
    }

